import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"WeCom（WeWork）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/wecom.md","filePath":"ja/integrations/channels/wecom.md","lastUpdated":1792323081000}'),n={name:"ja/integrations/channels/wecom.md"};function l(s,t,i,h,d,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="wecom-wework" tabindex="-1">WeCom（WeWork） <a class="header-anchor" href="#wecom-wework" aria-label="Permalink to &quot;WeCom（WeWork）&quot;">​</a></h1><p>Memoh Bot を WeCom（企業微信）につなぎ、組織の WeCom ワークスペース内でユーザーとプライベートチャットをしたり、グループチャットで協働したりできるようにします。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>Bot アプリの作成に使う、<a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom 管理コンソール</a> の管理者権限。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-wecom-管理コンソールで-bot-を作成する" tabindex="-1">1. WeCom 管理コンソールで Bot を作成する <a class="header-anchor" href="#_1-wecom-管理コンソールで-bot-を作成する" aria-label="Permalink to &quot;1. WeCom 管理コンソールで Bot を作成する&quot;">​</a></h3><p>WeCom 管理コンソールで次を行います。</p><ol><li><a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom 管理コンソール</a> にログインします。</li><li><strong>アプリ管理</strong> 配下の <strong>カスタムアプリ</strong> または <strong>Bot 管理</strong> に移動します。</li><li>新しい Bot アプリを作成します。</li><li><strong>Bot ID</strong> と <strong>Secret</strong> の認証情報を控えます。</li></ol><blockquote><p>公式ドキュメント：<a href="https://developer.work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom オープンプラットフォーム</a> · <a href="https://developer.work.weixin.qq.com/document/path/91770" target="_blank" rel="noreferrer">WeCom Bot ドキュメント</a></p></blockquote><h3 id="_2-memoh-でチャネルを追加する" tabindex="-1">2. Memoh でチャネルを追加する <a class="header-anchor" href="#_2-memoh-でチャネルを追加する" aria-label="Permalink to &quot;2. Memoh でチャネルを追加する&quot;">​</a></h3><p>Memoh で次を行います。</p><ol><li>Bot の <strong>プラットフォーム</strong> タブを開きます。</li><li><strong>Add Channel</strong> をクリックし、<strong>WeCom</strong> を選択します。</li><li><strong>Bot ID</strong> と <strong>Secret</strong> を入力します。カスタムの <strong>WebSocket URL</strong> は必要な場合のみ設定します。</li><li><strong>Save and Enable</strong> をクリックします。</li></ol><p>有効にすると、Memoh は WebSocket で WeCom に接続し、メッセージの受信を開始します。</p><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><strong>Bot ID</strong></td><td>はい</td><td>WeCom におけるこの Bot の識別子。</td></tr><tr><td><strong>Secret</strong></td><td>はい</td><td>Bot の認証用クレデンシャル。</td></tr><tr><td><strong>WebSocket URL</strong></td><td>いいえ</td><td>カスタムの WebSocket エンドポイント。空の場合はデフォルトのエンドポイントを使用します。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>プライベートチャットで Bot に <code>/help</code> を送るか、グループチャットで Bot を @メンションして <code>/help</code> を送ります。Bot がコマンド一覧を返せば、チャネルは接続できています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Bot は WeCom のグループチャットでも使えます。グループ内で Bot を @メンションすると返信します。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。認証情報を更新するときは、同じパネルで <strong>Bot ID</strong> / <strong>Secret</strong> を更新して保存してください。</p>',21)])])}const p=e(n,[["render",l]]);export{g as __pageData,p as default};
